import React, { useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import "./PaymentPage.css"; // Add your CSS file

function PaymentPage() {
  const navigate = useNavigate();
  const location = useLocation(); // Booking details passed via navigate
  const bookingDetails = location.state;

  const [paymentMethod, setPaymentMethod] = useState("");
  const [formData, setFormData] = useState({
    cardNumber: "",
    expiry: "",
    cvv: "",
    upiId: "",
    bankName: "",
    accountNumber: ""
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const validateCardNumber = (num) => /^\d{13,19}$/.test(num.replace(/\D/g, ""));
  const validateExpiry = (exp) => {
    if (!/^\d{2}\/\d{2}$/.test(exp)) return false;
    const [month, year] = exp.split("/").map(Number);
    const now = new Date();
    const currentYear = now.getFullYear() % 100;
    const currentMonth = now.getMonth() + 1;
    return month >= 1 && month <= 12 && (year > currentYear || (year === currentYear && month >= currentMonth));
  };
  const validateCVV = (cvv) => /^\d{3,4}$/.test(cvv);

  const handlePayment = async () => {
    const userEmail = localStorage.getItem("userEmail"); // Email from login

    if (!userEmail) return alert("User email not found!");
    if (!bookingDetails) return alert("Booking details are missing!");

    // Payment validation
    if (paymentMethod === "card") {
      if (!validateCardNumber(formData.cardNumber)) return alert("Invalid card number.");
      if (!validateExpiry(formData.expiry)) return alert("Invalid expiry date.");
      if (!validateCVV(formData.cvv)) return alert("Invalid CVV.");
    } else if (paymentMethod === "upi") {
      if (!formData.upiId.includes("@")) return alert("Invalid UPI ID.");
    } else if (paymentMethod === "netbanking") {
      if (!formData.bankName || !formData.accountNumber) return alert("Fill Net Banking details.");
    } else {
      return alert("Select a payment method.");
    }

    try {
      // Send email
      const response = await fetch("http://localhost:8081/api/send-email", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: userEmail, bookingDetails }),
      });

      const result = await response.text();
      alert(result); // Show backend response

      if (result.includes("success")) {
        navigate("/success", { state: bookingDetails }); // Navigate to success page
      }

    } catch (err) {
      console.error(err);
      alert("Failed to send email: " + err.message);
    }
  };

  return (
    <div className="payment-container">
      <h2>Payment Page</h2>

      <div className="payment-methods">
        <label>
          <input type="radio" name="paymentMethod" value="card" onChange={(e) => setPaymentMethod(e.target.value)} /> Credit/Debit Card
        </label>
        <label>
          <input type="radio" name="paymentMethod" value="upi" onChange={(e) => setPaymentMethod(e.target.value)} /> UPI
        </label>
        <label>
          <input type="radio" name="paymentMethod" value="netbanking" onChange={(e) => setPaymentMethod(e.target.value)} /> Net Banking
        </label>
      </div>

      {paymentMethod === "card" && (
        <div className="card-form">
          <input type="text" name="cardNumber" placeholder="Card Number" onChange={handleChange} />
          <input type="text" name="expiry" placeholder="MM/YY" onChange={handleChange} />
          <input type="text" name="cvv" placeholder="CVV" onChange={handleChange} />
        </div>
      )}

      {paymentMethod === "upi" && (
        <div className="upi-form">
          <input type="text" name="upiId" placeholder="UPI ID" onChange={handleChange} />
        </div>
      )}

      {paymentMethod === "netbanking" && (
        <div className="netbanking-form">
          <input type="text" name="bankName" placeholder="Bank Name" onChange={handleChange} />
          <input type="text" name="accountNumber" placeholder="Account Number" onChange={handleChange} />
        </div>
      )}

      <button className="pay-button" onClick={handlePayment}>Pay Now</button>
    </div>
  );
}

export default PaymentPage;
